"""Persistent reservation / compilation controller (protocol 3.0.0)."""
from util import (Invalid, need, is_int, req_int, req_id, req_exact_keys, req_list,
                  req_bool, req_window, req_envelope, sorted_ids,
                  LIM_TICK, LIM_RATE, LIM_PERIOD, LIM_REV, LIM_NODE, LIM_LINK,
                  MAX_LINKS, MAX_BOOKINGS, MAX_ENV_TOTAL, MAX_AUDIT_TICKS,
                  MAX_EDIT_CHANGES, MAX_PARTICIPANTS, MIN_PARTICIPANTS, MAX_LOAD_N)

ABOUT_REPLY = {'status': 'ok', 'protocol': 'forest-controller/3'}


def _err(code, rev):
    return {'status': 'error', 'code': code, 'rev': rev}


def _stale(rev):
    return {'status': 'stale', 'rev': rev}


class Booking(object):
    __slots__ = ('id', 'owner', 's', 'e', 'env', 'live', 'origin')

    def __init__(self, bid, owner, s, e, env, origin):
        self.id = bid
        self.owner = owner
        self.s = s
        self.e = e
        self.env = env
        self.live = True
        self.origin = origin


class Service(object):
    def __init__(self):
        self.loaded = False
        self.rev = 0
        self.now = 0
        self.n = 0
        self.links = []          # list of (u, v)
        self.caps = []           # list of per-direction capacity
        self.bookings = {}       # id -> Booking
        self.preps = {}          # id -> dict(payload, base_rev, outcome)
        self.compiler = None

    # ------------------------------------------------------------------ helpers
    def live_bookings(self):
        return [b for b in self.bookings.values() if b.live]

    def used_at(self, link, t):
        tot = 0
        for b in self.bookings.values():
            if b.live and b.s <= t < b.e:
                tot += b.env.get(link, 0)
        return tot

    def sample_at(self, t):
        out = []
        for l in range(len(self.links)):
            out.append(self.caps[l] - self.used_at(l, t))
        return out

    def live_ids(self):
        return sorted_ids([b.id for b in self.bookings.values() if b.live])

    def event_ticks_from(self, start):
        """Ticks >= start where the set of active live leases can grow."""
        ticks = set([start])
        for b in self.bookings.values():
            if b.live and b.s > start:
                ticks.add(b.s)
        return sorted(ticks)

    # ------------------------------------------------------------------ dispatch
    def handle(self, request):
        if type(request) is not dict:
            raise Invalid()
        if 'op' not in request:
            raise Invalid()
        op = request['op']
        if type(op) is not str:
            raise Invalid()
        method = getattr(self, '_op_' + op, None)
        if method is None:
            raise Invalid()
        return method(request)

    # ------------------------------------------------------------------ about
    def _op_about(self, request):
        req_exact_keys(request, ['op'])
        return dict(ABOUT_REPLY)

    # ------------------------------------------------------------------ load
    def _op_load(self, request):
        req_exact_keys(request, ['op', 'n', 'links', 'bookings'])
        n = req_int(request['n'], 2, MAX_LOAD_N)
        raw_links = req_list(request['links'])
        if len(raw_links) > MAX_LINKS:
            raise Invalid()
        links = []
        seen_pairs = set()
        for entry in raw_links:
            if type(entry) is not list or len(entry) != 3:
                raise Invalid()
            u = req_int(entry[0], 0, n - 1)
            v = req_int(entry[1], 0, n - 1)
            cap = req_int(entry[2], 0, LIM_RATE)
            if u == v:
                raise Invalid()
            key = (u, v) if u < v else (v, u)
            if key in seen_pairs:
                raise Invalid()
            seen_pairs.add(key)
            links.append((u, v, cap))
        raw_bookings = req_list(request['bookings'])
        if len(raw_bookings) > MAX_BOOKINGS:
            raise Invalid()
        bookings = []
        ids = set()
        env_total = 0
        for entry in raw_bookings:
            if type(entry) is not dict:
                raise Invalid()
            req_exact_keys(entry, ['id', 'owner', 'window', 'envelope'])
            bid = req_id(entry['id'])
            owner = req_id(entry['owner'])
            window = req_window(entry['window'])
            env = req_envelope(entry['envelope'])
            if bid in ids:
                raise Invalid()
            ids.add(bid)
            env_total += len(env)
            for l in env:
                if l >= len(links):
                    raise Invalid()
            bookings.append((bid, owner, window, env))
        if env_total > MAX_ENV_TOTAL:
            raise Invalid()

        if self.loaded:
            return _err('ALREADY_LOADED', self.rev)

        # first load: validate the committed book against base capacity
        starts = set([0])
        for (_bid, _owner, (s, _e), _env) in bookings:
            starts.add(s)
        for t in sorted(starts):
            for l in range(len(links)):
                used = 0
                for (_bid, _owner, (s, e), env) in bookings:
                    if s <= t < e:
                        used += env.get(l, 0)
                if used > links[l][2]:
                    raise Invalid()

        self.loaded = True
        self.n = n
        self.links = [(u, v) for (u, v, _c) in links]
        self.caps = [c for (_u, _v, c) in links]
        self.rev = 0
        self.now = 0
        for (bid, owner, (s, e), env) in bookings:
            self.bookings[bid] = Booking(bid, owner, s, e, env, 'load')
        return {'status': 'ok', 'rev': 0, 'now': 0}

    # ------------------------------------------------------------------ audit
    def _op_audit(self, request):
        req_exact_keys(request, ['op', 'at'])
        at = req_list(request['at'])
        if len(at) > MAX_AUDIT_TICKS:
            raise Invalid()
        ticks = [req_int(x, 0, LIM_TICK) for x in at]
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        for t in ticks:
            if t < self.now:
                return _err('TIME', self.rev)
        return {
            'status': 'ok',
            'rev': self.rev,
            'now': self.now,
            'leases': self.live_ids(),
            'samples': [[t, self.sample_at(t)] for t in ticks],
        }

    # ------------------------------------------------------------------ advance
    def _op_advance(self, request):
        req_exact_keys(request, ['op', 'time'])
        t = req_int(request['time'], 0, LIM_TICK)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        if t < self.now:
            return _err('TIME', self.rev)
        expired = []
        for b in self.bookings.values():
            if b.live and b.e <= t:
                b.live = False
                expired.append(b.id)
        self.now = t
        self.rev += 1
        return {
            'status': 'ok',
            'rev': self.rev,
            'now': t,
            'expired': sorted_ids(expired),
        }

    # ------------------------------------------------------------------ edit
    def _op_edit(self, request):
        req_exact_keys(request, ['op', 'rev', 'changes', 'force'])
        r = req_int(request['rev'], 0, LIM_REV)
        raw = req_list(request['changes'])
        if len(raw) > MAX_EDIT_CHANGES:
            raise Invalid()
        changes = []
        seen = set()
        for entry in raw:
            if type(entry) is not list or len(entry) != 2:
                raise Invalid()
            l = req_int(entry[0], 0, LIM_LINK)
            c = req_int(entry[1], 0, LIM_RATE)
            if l in seen:
                raise Invalid()
            seen.add(l)
            changes.append((l, c))
        force = req_bool(request['force'])
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        if r != self.rev:
            return _stale(self.rev)
        for (l, _c) in changes:
            if l >= len(self.links):
                return _err('REFERENCE', self.rev)

        proposed = list(self.caps)
        for (l, c) in changes:
            proposed[l] = c

        if not force:
            witness = None
            for t in self.event_ticks_from(self.now):
                for (l, c) in changes:
                    if c < self.caps[l]:
                        u = self.used_at(l, t)
                        if u > c:
                            witness = (l, t, u, c)
                            break
                if witness is not None:
                    break
            if witness is not None:
                (l, t, u, c) = witness
                return {'status': 'blocked', 'rev': self.rev, 'link': l,
                        'time': t, 'used': u, 'capacity': c}
            self.caps = proposed
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'cancelled': []}

        # forced: revoke every live lease with a positive rate on a link whose
        # capacity actually decreases.
        decreased = set([l for (l, c) in changes if c < self.caps[l]])
        revoked = []
        if decreased:
            for b in self.bookings.values():
                if not b.live:
                    continue
                for l in decreased:
                    if b.env.get(l, 0) > 0:
                        b.live = False
                        revoked.append(b.id)
                        break
        self.caps = proposed
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'cancelled': sorted_ids(revoked)}

    # ------------------------------------------------------------------ prepare
    def _op_prepare(self, request):
        from compiler import compile_prepare
        req_exact_keys(request, ['op', 'id', 'owner', 'window', 'period',
                                 'participants', 'envelope', 'rev'])
        pid = req_id(request['id'])
        owner = req_id(request['owner'])
        window = req_window(request['window'])
        period = req_int(request['period'], 1, LIM_PERIOD)
        rawp = req_list(request['participants'])
        if len(rawp) < MIN_PARTICIPANTS or len(rawp) > MAX_PARTICIPANTS:
            raise Invalid()
        parts = []
        seen = set()
        total = 0
        for entry in rawp:
            if type(entry) is not list or len(entry) != 2:
                raise Invalid()
            v = req_int(entry[0], 0, LIM_NODE)
            rv = req_int(entry[1], 0, LIM_RATE)
            if v in seen:
                raise Invalid()
            seen.add(v)
            parts.append((v, rv))
            total += rv
        if total <= 0:
            raise Invalid()
        env = req_envelope(request['envelope'])
        r = req_int(request['rev'], 0, LIM_REV)
        if not self.loaded:
            return _err('NOT_LOADED', 0)

        key = (owner, window[0], window[1], period, r,
               tuple(sorted(parts)), tuple(sorted(env.items())))

        # identity / conflict cache precedes revision checks
        if pid in self.preps:
            rec = self.preps[pid]
            if rec['key'] == key:
                return {'status': 'replay', 'id': pid, 'rev': self.rev,
                        'base_rev': rec['base_rev'], 'outcome': rec['outcome']}
            return _err('CONFLICT', self.rev)
        if pid in self.bookings:
            return _err('CONFLICT', self.rev)

        if r != self.rev:
            return _stale(self.rev)
        for (v, _rv) in parts:
            if v >= self.n:
                return _err('REFERENCE', self.rev)
        for l in env:
            if l >= len(self.links):
                return _err('REFERENCE', self.rev)
        s, e = window
        if s < self.now:
            return _err('TIME', self.rev)
        if (e - s) % period != 0:
            return _err('WINDOW', self.rev)

        reply = compile_prepare(self, pid, s, e, period, parts, env)
        self.preps[pid] = {'key': key, 'base_rev': self.rev,
                           'outcome': 'prepared' if reply['status'] == 'prepared' else 'denied'}
        return reply

    # ------------------------------------------------------------------ commit
    def _op_commit(self, request):
        req_exact_keys(request, ['op', 'id', 'owner', 'rev'])
        cid = req_id(request['id'])
        owner = req_id(request['owner'])
        r = req_int(request['rev'], 0, LIM_REV)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        prep = self.preps.get(cid)
        if prep is None and cid not in self.bookings:
            return _err('MISSING', self.rev)
        rec_owner = None
        if prep is not None:
            rec_owner = prep['key'][0]
        else:
            rec_owner = self.bookings[cid].owner
        if rec_owner != owner:
            return _err('OWNER', self.rev)

        b = self.bookings.get(cid)
        if b is not None:
            if b.live:
                return {'status': 'ok', 'id': cid, 'rev': self.rev, 'replay': True}
            return _err('GONE', self.rev)
        # pure preparation record
        if prep['outcome'] == 'denied':
            return _err('DENIED', self.rev)
        if r != self.rev or prep['base_rev'] != self.rev:
            return _stale(self.rev)
        s, e = prep['key'][1], prep['key'][2]
        env = dict(prep['key'][6])
        self.bookings[cid] = Booking(cid, owner, s, e, env, 'prepare')
        self.rev += 1
        return {'status': 'ok', 'id': cid, 'rev': self.rev, 'replay': False}

    # ------------------------------------------------------------------ cancel
    def _op_cancel(self, request):
        req_exact_keys(request, ['op', 'id', 'owner', 'rev'])
        cid = req_id(request['id'])
        owner = req_id(request['owner'])
        r = req_int(request['rev'], 0, LIM_REV)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        if r != self.rev:
            return _stale(self.rev)
        b = self.bookings.get(cid)
        if b is None or not b.live:
            return _err('MISSING', self.rev)
        if b.owner != owner:
            return _err('OWNER', self.rev)
        b.live = False
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'released': cid}


SERVICE = Service()


def handle(request):
    return SERVICE.handle(request)
